/**
 * Responsive photo for the marketing pages.
 *
 * The files are generated by `npm run images` into
 * `public/images/photos/v1`. AVIF is served first, with WebP as the fallback;
 * every source has the same crop so the layout does not shift between formats.
 */

export type PhotoName =
  | "nigeria-omniel"
  | "students-with-omniel"
  | "creatives-on-laptops"
  | "black-for-teams"
  | "students-omniel"
  | "for-teams";

const widths = [480, 768, 1200, 1600] as const;

const dimensions: Record<PhotoName, { width: number; height: number }> = {
  "nigeria-omniel": { width: 1600, height: 800 },
  "students-with-omniel": { width: 1600, height: 900 },
  "creatives-on-laptops": { width: 1600, height: 1200 },
  "black-for-teams": { width: 1600, height: 1200 },
  "students-omniel": { width: 1600, height: 900 },
  "for-teams": { width: 1600, height: 1200 },
};

const base = "/images/photos/v1";

function srcSet(name: PhotoName, extension: "avif" | "webp") {
  return widths.map((width) => `${base}/${name}-${width}.${extension} ${width}w`).join(", ");
}

export function ResponsivePhoto({
  name,
  alt,
  sizes = "100vw",
  className,
  loading = "lazy",
  fetchPriority,
}: {
  name: PhotoName;
  alt: string;
  sizes?: string;
  className?: string;
  loading?: "eager" | "lazy";
  fetchPriority?: "high" | "low" | "auto";
}) {
  const size = dimensions[name];

  return (
    <picture className="block">
      <source type="image/avif" srcSet={srcSet(name, "avif")} sizes={sizes} />
      <source type="image/webp" srcSet={srcSet(name, "webp")} sizes={sizes} />
      <img
        src={`${base}/${name}-1200.webp`}
        srcSet={srcSet(name, "webp")}
        sizes={sizes}
        alt={alt}
        width={size.width}
        height={size.height}
        loading={loading}
        decoding="async"
        fetchPriority={fetchPriority}
        className={className}
      />
    </picture>
  );
}
